/**
 * Prompt-library registry — the computed catalog of all 403 reference
 * /3d-prompts detail routes (t69).
 *
 * The raw slug list, model membership, hub facts and card titles live in
 * prompts-registry-data.ts (generated by scripts/gen-prompts-registry.py
 * from the live reference crawl — see recon/3d-prompts-tree.md).
 * Everything here is DERIVED from that data: families, display titles,
 * the catalog order, pagination math, hub display info, and the census.
 * The census is computed at module load — never hand-set — so the
 * numbers the pages and tests quote cannot drift from the data they
 * describe.
 *
 * Pagination mirrors the reference's own math: 24 cards per index page,
 * 17 pages (16 × 24 + 19 = 403). Hub pagination: 24 members per page,
 * page counts as crawled (gpt-6-astra 11, claude-fable-5.1 4, others 1).
 * Ordering differs from the reference's feed honestly: written prompts
 * first (they are the ones a reader can actually use), then the
 * community catalog, alphabetical — this clone has no community feed
 * dates to sort by and will not fabricate them.
 */
import type { PromptArticleDef, PromptEntry, PromptHubInfo, PromptVideoRef } from "./prompts-types";
import { PROMPT_ARTICLES_A } from "./prompts-content-a";
import { PROMPT_ARTICLES_B } from "./prompts-content-b";
import { PROMPT_ARTICLES_C } from "./prompts-content-c";
import {
  REFERENCE_HUB_CLAIMED,
  REFERENCE_HUB_MEMBERS,
  REFERENCE_HUB_ORDER,
  REFERENCE_HUB_PAGE_COUNT,
  REFERENCE_PROMPT_SLUGS,
  REFERENCE_PROMPT_TITLES,
  WRITTEN_PROMPT_SLUGS,
} from "./prompts-registry-data";

/** All 36 written prompt articles, one array, slug-unique. */
export const PROMPT_ARTICLES: PromptArticleDef[] = [
  ...PROMPT_ARTICLES_A,
  ...PROMPT_ARTICLES_B,
  ...PROMPT_ARTICLES_C,
];

const WRITTEN_BY_SLUG = new Map(PROMPT_ARTICLES.map((a) => [a.slug, a]));

// -- invariants: the written set must exactly match the curated data ------
const writtenSlugs = new Set(WRITTEN_PROMPT_SLUGS);
const articleSlugs = new Set(PROMPT_ARTICLES.map((a) => a.slug));
if (writtenSlugs.size !== articleSlugs.size || [...writtenSlugs].some((s) => !articleSlugs.has(s))) {
  throw new Error("prompt registry: WRITTEN_PROMPT_SLUGS and PROMPT_ARTICLES disagree");
}

// -- model display names ----------------------------------------------------

/** Display name for a model hub slug ("gpt-6-astra" -> "GPT-6 Astra"). */
export const MODEL_DISPLAY_NAME: Record<string, string> = {
  "gpt-6.1-sol": "GPT-6.1 Sol",
  "sonnet-5.5": "Sonnet 5.5",
  "gpt-6-astra": "GPT-6 Astra",
  "opus-5.5": "Opus 5.5",
  "claude-opus-5.5": "Claude Opus 5.5",
  "gpt-6-sol": "GPT-6 Sol",
  "gpt-6-luna": "GPT-6 Luna",
  "claude-fable-5.1": "Claude Fable 5.1",
  "kimi-k3": "Kimi K3",
  "claude-fable-5": "Claude Fable 5",
  "claude-opus-5": "Claude Opus 5",
};

/** Hub membership reverse index: slug -> model slugs (display order). */
const MEMBER_OF: Record<string, string[]> = {};
for (const model of REFERENCE_HUB_ORDER) {
  for (const slug of REFERENCE_HUB_MEMBERS[model]) {
    (MEMBER_OF[slug] ??= []).push(model);
  }
}

/** The reference's model association(s) for a route, display names. */
export function promptModels(slug: string): string[] {
  return (MEMBER_OF[slug] ?? []).map((m) => MODEL_DISPLAY_NAME[m] ?? m);
}

// -- the catalog -----------------------------------------------------------

function entryFor(slug: string): PromptEntry {
  const article = WRITTEN_BY_SLUG.get(slug);
  return {
    slug,
    family: article ? "written" : "community",
    ...(article ? { article } : {}),
    title: article?.title ?? REFERENCE_PROMPT_TITLES[slug] ?? slug,
    models: promptModels(slug),
  };
}

/**
 * The full catalog in display order: the 36 written prompts first (group
 * order — characters, props, environments, dioramas — then slug), then the
 * community catalog alphabetical. Our prompts first because they are the
 * ones a reader can actually run; the rest is the honest route catalog.
 */
const GROUP_ORDER: Record<string, number> = { characters: 0, props: 1, environments: 2, dioramas: 3 };

export const PROMPT_CATALOG: PromptEntry[] = REFERENCE_PROMPT_SLUGS.map(entryFor).sort((a, b) => {
  const wa = a.family === "written" ? 0 : 1;
  const wb = b.family === "written" ? 0 : 1;
  if (wa !== wb) return wa - wb;
  if (wa === 0) {
    const ga = GROUP_ORDER[a.article?.group ?? "dioramas"];
    const gb = GROUP_ORDER[b.article?.group ?? "dioramas"];
    if (ga !== gb) return ga - gb;
  }
  return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
});

/** Find a catalog row by slug (any of the 403). */
export function findPromptEntry(slug: string): PromptEntry | undefined {
  return PROMPT_CATALOG.find((e) => e.slug === slug);
}

// -- the census (computed, never hand-set) ---------------------------------

export const PROMPT_CENSUS = {
  total: PROMPT_CATALOG.length,
  written: PROMPT_CATALOG.filter((e) => e.family === "written").length,
  community: PROMPT_CATALOG.filter((e) => e.family === "community").length,
  memberships: REFERENCE_HUB_ORDER.reduce((n, m) => n + REFERENCE_HUB_MEMBERS[m].length, 0),
} as const;

// -- index pagination ------------------------------------------------------

/** Cards per index page — the reference's own math (16 × 24 + 19 = 403). */
export const PROMPT_PAGE_SIZE = 24;

/** Total index pages (the reference serves /3d-prompts/2 … /17). */
export const PROMPT_PAGE_COUNT = Math.ceil(PROMPT_CATALOG.length / PROMPT_PAGE_SIZE);

/** The catalog slice for a 1-based index page number. */
export function promptPage(page: number): PromptEntry[] {
  if (page < 1 || page > PROMPT_PAGE_COUNT) return [];
  return PROMPT_CATALOG.slice((page - 1) * PROMPT_PAGE_SIZE, page * PROMPT_PAGE_SIZE);
}

/** A numeric path segment is an index page iff it is 2..PROMPT_PAGE_COUNT
 * (page 1 is the bare /3d-prompts route, like the reference). */
export function isPromptIndexPage(slug: string): boolean {
  if (!/^\d+$/.test(slug)) return false;
  const n = Number(slug);
  return n >= 2 && n <= PROMPT_PAGE_COUNT;
}

// -- model hubs --------------------------------------------------------------

/** Display info for every hub, in the reference index rail's order. */
export const PROMPT_HUBS: PromptHubInfo[] = REFERENCE_HUB_ORDER.map((slug) => ({
  slug,
  name: MODEL_DISPLAY_NAME[slug] ?? slug,
  claimed: REFERENCE_HUB_CLAIMED[slug],
  members: REFERENCE_HUB_MEMBERS[slug].length,
  pages: REFERENCE_HUB_PAGE_COUNT[slug],
}));

/** Find a hub by its slug. */
export function findPromptHub(slug: string): PromptHubInfo | undefined {
  return PROMPT_HUBS.find((h) => h.slug === slug);
}

/** Hub rows are the member catalog entries, in crawled document order. */
export function promptHubMembers(hub: PromptHubInfo): PromptEntry[] {
  return REFERENCE_HUB_MEMBERS[hub.slug]
    .map((slug) => findPromptEntry(slug))
    .filter((e): e is PromptEntry => Boolean(e));
}

/** Hub pagination: members per page (24, as the reference paginates). */
export const HUB_PAGE_SIZE = 24;

/** The member slice for a 1-based hub page number ([] when out of range). */
export function promptHubPage(hub: PromptHubInfo, page: number): PromptEntry[] {
  if (page < 1 || page > hub.pages) return [];
  const members = promptHubMembers(hub);
  return members.slice((page - 1) * HUB_PAGE_SIZE, page * HUB_PAGE_SIZE);
}

// -- route constants --------------------------------------------------------

/** Reserved path segments that must never resolve as detail slugs. */
export const PROMPT_RESERVED_SLUGS = ["models"] as const;

